import sys
from bisect import bisect_left

def by_count(arr):
    m = len(arr)
    cur = [[0]] + [[] for _ in range(m)]
    for x in arr:
        for c in range(m - 1, -1, -1):
            if cur[c]:
                cur[c + 1].extend(v + x for v in cur[c])
    return cur

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + 2 * n]))
    total = sum(a)
    L = by_count(a[:n])
    R = by_count(a[n:])
    best = None
    for c in range(n + 1):
        right = sorted(R[n - c])
        for x in L[c]:
            t = (total - 2 * x) // 2
            p = bisect_left(right, t)
            for q in (p - 1, p, p + 1):
                if 0 <= q < len(right):
                    d = abs(total - 2 * (x + right[q]))
                    if best is None or d < best:
                        best = d
    print(best)

main()

